"""Experiment 4 (30 Sept 2026): text generated by a LOCAL language model whose own hidden states are available.
Same posts, prompts, personas and labels as Experiment 3 (Z = the 3000 posts of gen_claude-haiku-4-5_n3000.jsonl), but the
comment X~, the summary Y~0 (H0) and the label-conditioned summary Y~1 (H1) are sampled from Qwen3-1.7B on this machine, and the
model's hidden states for the post are stored as views of Z: the mean over the post tokens and the state at the last prompt
token, at the last layer and at the middle layer (a function of Z only: the states are taken from the summary prompt, which
contains nothing but the post). Not a sufficient statistic of the generator (it attends to every prompt token), but the
representation the generator itself computes, to be compared with E1 and E2 at equal dimension (principal components).

Phases (resumable): gen    -> ~/.cache/ci_text/llm/gen_qwen3-1.7b_n3000.jsonl (same record format as citext.llm_gen)
                    hidden -> ~/.cache/ci_text/llm/hidden_qwen3-1.7b_n3000.npz
                    test   -> results/exp4_local_tests.csv, exp4_local_curve.csv, summary_exp4.json (least squares only, by the rule)
                    plots  -> figures/exp4_local_dims.pdf
usage: python experiments/exp4_local.py [--only gen,hidden,test,plots] [--n 3000] [--batch 10] [--model Qwen/Qwen3-1.7B]
"""
from __future__ import annotations
import argparse, json, os, re, sys, time
from pathlib import Path
import numpy as np, pandas as pd
HERE = Path(__file__).resolve().parent
CODE = Path(os.environ.get("CI_TEXT_CODE_DIR", HERE.parent)); sys.path.insert(0, str(CODE))
from citext.estimators import fit_predict_crossfit, partial_r2_benchmark, rv_alpha, critical_value, config_feasible, crossfit_folds
from citext.paths import RESULTS_DIR, CACHE_DIR, FIG_DIR
from citext.llm_gen import SYSTEM, X_INSTR, Y0_INSTR, Y1_INSTR, PERSONAS
from citext.text_semi import E1_NAME, E2_NAME, embed_texts
LLM = CACHE_DIR / "llm"; SOURCE = LLM / "gen_claude-haiku-4-5_n3000.jsonl"
ALPHA, SEED, K = 0.05, 0, 5
LABEL_RE = re.compile(r"\s*(POSITIVE|NEGATIVE|NEUTRAL)\W*$", re.I)
t0 = time.time()
def log(*a): print(f"[{time.time()-t0:6.0f}s]", *a, flush=True)
def tag(model): return model.split("/")[-1].lower()
def gen_path(model, n): return LLM / f"gen_{tag(model)}_n{n}.jsonl"
def hid_path(model, n): return LLM / f"hidden_{tag(model)}_n{n}.npz"

def source_posts(n):
    rows = [json.loads(l) for l in SOURCE.read_text().splitlines() if l.strip()]
    return [(r["idx"], r["Z"]) for r in rows][:n]

# ------------------------------------------------------------------ model
def load_model(model):
    import torch; from transformers import AutoTokenizer, AutoModelForCausalLM
    dev = "mps" if torch.backends.mps.is_available() else "cpu"
    tok = AutoTokenizer.from_pretrained(model); tok.padding_side = "left"
    if tok.pad_token is None: tok.pad_token = tok.eos_token
    m = AutoModelForCausalLM.from_pretrained(model, dtype=torch.bfloat16 if dev == "mps" else torch.float32).to(dev).eval()
    log(f"{model} loaded on {dev}: {sum(p.numel() for p in m.parameters())/1e9:.2f}B parameters, {m.config.num_hidden_layers} layers, hidden {m.config.hidden_size}")
    return tok, m, dev

def chat(tok, user):
    return tok.apply_chat_template([{"role": "system", "content": SYSTEM}, {"role": "user", "content": user}], tokenize=False, add_generation_prompt=True, enable_thinking=False)

def generate(tok, m, dev, prompts, max_new, seed):
    import torch
    enc = tok(prompts, return_tensors="pt", padding=True).to(dev); torch.manual_seed(seed)
    with torch.no_grad():
        out = m.generate(**enc, do_sample=True, temperature=1.0, top_p=0.95, top_k=0, max_new_tokens=max_new, pad_token_id=tok.pad_token_id)
    texts = tok.batch_decode(out[:, enc["input_ids"].shape[1]:], skip_special_tokens=True)
    if dev == "mps": torch.mps.empty_cache()
    return [t.strip() for t in texts]

# ------------------------------------------------------------------ gen
def phase_gen(model, n, batch):
    path = gen_path(model, n); done = {json.loads(l)["idx"] for l in path.read_text().splitlines() if l.strip()} if path.exists() else set()
    posts = [(i, z) for i, z in source_posts(n) if i not in done]; log(f"gen: {len(done)} done, {len(posts)} to do")
    if not posts: return
    tok, m, dev = load_model(model); rng = np.random.default_rng(SEED)
    persona_of = {i: PERSONAS[int(rng.integers(len(PERSONAS)))] for i, _ in source_posts(n)}   # persona by post index, reproducible across resumes
    with open(path, "a") as f:
        for k in range(0, len(posts), batch):
            chunk = posts[k:k + batch]; tb = time.time()
            X = generate(tok, m, dev, [chat(tok, X_INSTR.format(Z=z, PERSONA=persona_of[i])) for i, z in chunk], 160, SEED + k)
            labels, Xs = [], []
            for x in X:
                mm = LABEL_RE.search(x); labels.append(mm.group(1).upper() if mm else None); Xs.append(LABEL_RE.sub("", x).strip() if mm else x)
            Y0 = generate(tok, m, dev, [chat(tok, Y0_INSTR.format(Z=z)) for i, z in chunk], 160, SEED + k + 1)
            Y1 = generate(tok, m, dev, [chat(tok, Y1_INSTR.format(Z=z, LABEL=(lab or "NEUTRAL").lower())) for (i, z), lab in zip(chunk, labels)], 160, SEED + k + 2)
            for (i, z), x, lab, y0, y1 in zip(chunk, Xs, labels, Y0, Y1):
                f.write(json.dumps({"idx": i, "Z": z, "X": x, "X_label": lab, "persona": persona_of[i], "Y0": y0, "Y1": y1, "usage": None, "stop": None, "model": model}) + "\n")
            f.flush(); log(f"  {k + len(chunk)}/{len(posts)} posts, {time.time() - tb:.1f} s per batch, labels missing {sum(l is None for l in labels)}")

# ------------------------------------------------------------------ hidden states
def phase_hidden(model, n, batch):
    import torch
    path = hid_path(model, n); posts = source_posts(n); tok, m, dev = load_model(model); L = m.config.num_hidden_layers; mid = L // 2
    prompts = [chat(tok, Y0_INSTR.format(Z=z)) for _, z in posts]   # the summary prompt: a function of the post only
    out = {k: [] for k in ("mean_last", "mean_mid", "tok_last", "tok_mid")}
    for k in range(0, len(prompts), batch):   # fixed batch composition (sorted by position) so that the vectors are reproducible
        enc = tok(prompts[k:k + batch], return_tensors="pt", padding=True, return_offsets_mapping=False).to(dev)
        with torch.no_grad():
            hs = m(**enc, output_hidden_states=True).hidden_states
        att = enc["attention_mask"].unsqueeze(-1).float()
        for name, layer in (("last", hs[-1]), ("mid", hs[mid])):
            h = layer.float()
            out[f"mean_{name}"].append(((h * att).sum(1) / att.sum(1)).cpu().numpy())   # mean over the prompt tokens (left padding excluded); the prompt is the post plus a fixed instruction
            out[f"tok_{name}"].append(h[:, -1, :].cpu().numpy())
        if dev == "mps": torch.mps.empty_cache()
        if (k // batch) % 20 == 0: log(f"  hidden {k + len(enc['input_ids'])}/{len(prompts)}")
    np.savez(path, idx=np.array([i for i, _ in posts]), **{k: np.vstack(v).astype(np.float32) for k, v in out.items()}, layers=np.array([L, mid]))
    log(f"hidden states saved: {path}")

# ------------------------------------------------------------------ test
def corr(rA, rB):
    a = rA / np.sqrt(np.mean(rA**2)); b = rB / np.sqrt(np.mean(rB**2)); rho = float(np.mean(a * b)); IF = a * b - rho / 2 * (a**2 + b**2)
    se = float(np.sqrt(np.mean(IF**2) / len(a))); from scipy.stats import norm
    return {"rho": rho, "se": se, "p": float(2 * norm.sf(abs(rho) / se)), "RV_alpha": float(rv_alpha(rho, se, ALPHA)), "reject": bool(abs(rho) > critical_value(0.0, se, ALPHA))}

def sentiment_axis(EX, EY, labels, folds):
    """Cross-fitted ridge direction from E1(comment) to the self-reported label, applied to the comment and to the summary (as in exp3_llm.py)."""
    from sklearn.linear_model import RidgeCV
    y = np.array([{"POSITIVE": 1.0, "NEUTRAL": 0.0, "NEGATIVE": -1.0}[l] for l in labels]); X = np.empty(len(y)); Y = np.empty(len(y))
    for tr, te in folds:
        r = RidgeCV(alphas=np.logspace(-2, 4, 13)).fit(EX[tr], y[tr]); X[te] = r.predict(EX[te]); Y[te] = r.predict(EY[te])
    return X, Y

def phase_test(model, n, n_sub):
    from sklearn.decomposition import PCA
    rows = [json.loads(l) for l in gen_path(model, n).read_text().splitlines() if l.strip()]; rows = [r for r in rows if r["X_label"] and r["X"] and r["Y0"] and r["Y1"]]
    rows.sort(key=lambda r: r["idx"]); idx = np.array([r["idx"] for r in rows]); H = np.load(hid_path(model, n)); pos = {i: j for j, i in enumerate(H["idx"])}; sel = np.array([pos[i] for i in idx])
    log(f"{len(rows)} rows with a label ({len(rows)/n:.1%})")
    Z = [r["Z"] for r in rows]; E1Z, E2Z = embed_texts(Z, E1_NAME), embed_texts(Z, E2_NAME); E1X = embed_texts([r["X"] for r in rows], E1_NAME)
    E1Y = {"H0": embed_texts([r["Y0"] for r in rows], E1_NAME), "H1": embed_texts([r["Y1"] for r in rows], E1_NAME)}
    folds = crossfit_folds(len(rows), K, SEED); labels = [r["X_label"] for r in rows]
    XY = {h: sentiment_axis(E1X, E1Y[h], labels, folds) for h in ("H0", "H1")}
    views = {"E1": E1Z, "E2": E2Z}; DIMS = (64, 128, 256, 384, 768)
    for name in ("mean_last", "mean_mid", "tok_last", "tok_mid"):
        Hv = H[name][sel]; P = PCA(max(DIMS), random_state=SEED).fit(Hv); T = P.transform(Hv)
        for d in DIMS: views[f"{name}:{d}"] = T[:, :d]
        views[f"[E1,{name}:256]"] = np.hstack([E1Z, T[:, :256]])
    res = []
    for h, (X, Y) in XY.items():
        marg = corr(X - X.mean(), Y - Y.mean()); res.append({"hyp": h, "psi": "none", "d": 0, "n": len(X), **marg})
        for pn, Psi in views.items():
            if not config_feasible(len(X), Psi.shape[1], K): log(f"  {pn}: not reported"); continue
            rA = X - fit_predict_crossfit(Psi, X, K, SEED, "ols", folds); rB = Y - fit_predict_crossfit(Psi, Y, K, SEED, "ols", folds); r = corr(rA, rB)
            r.update({"R2_X": float(1 - np.mean(rA**2) / np.var(X)), "R2_Y": float(1 - np.mean(rB**2) / np.var(Y))})
            if pn != "E1" and Psi.shape[1] + E1Z.shape[1] <= len(folds[0][0]) / 2.5:
                bA = partial_r2_benchmark(X, E1Z, Psi, "ols", K, SEED, folds); bB = partial_r2_benchmark(Y, E1Z, Psi, "ols", K, SEED, folds); r["bench_E1"] = float(np.sqrt(bA["r2"] * bB["r2"]))
            res.append({"hyp": h, "psi": pn, "d": Psi.shape[1], "n": len(X), **r}); log(f"{h} psi={pn} (d={Psi.shape[1]}): rho={r['rho']:.4f} se={r['se']:.4f} R2X={r['R2_X']:.3f} R2Y={r['R2_Y']:.3f}" + (f" bench={r['bench_E1']:.4f}" if "bench_E1" in r else ""))
        pd.DataFrame(res).to_csv(RESULTS_DIR / "exp4_local_tests.csv", index=False)
    # learning curve under H0 at n = 1000, 2000 (subsamples) and the full sample, for E1 and the generator's states at 256 dimensions
    X, Y = XY["H0"]; rng = np.random.default_rng(SEED); curve = []
    for nn in (1000, 2000):
        for s in range(n_sub):
            ii = rng.choice(len(X), nn, replace=False); f = crossfit_folds(nn, K, s)
            for pn in ("E1", "mean_last:256", "tok_last:256"):
                Psi = views[pn][ii]
                if not config_feasible(nn, Psi.shape[1], K): continue
                rA = X[ii] - fit_predict_crossfit(Psi, X[ii], K, s, "ols", f); rB = Y[ii] - fit_predict_crossfit(Psi, Y[ii], K, s, "ols", f); curve.append({"n": nn, "sub": s, "psi": pn, **corr(rA, rB)})
        log(f"curve n={nn} done")
    pd.DataFrame(curve).to_csv(RESULTS_DIR / "exp4_local_curve.csv", index=False)
    n_generated = sum(1 for l in gen_path(model, n).read_text().splitlines() if l.strip())
    json.dump({"model": model, "n_rows": len(rows), "n_generated": n_generated, "labels": pd.Series(labels).value_counts().to_dict(), "unadjusted": {h: corr(XY[h][0] - XY[h][0].mean(), XY[h][1] - XY[h][1].mean())["rho"] for h in XY},
               "layers": H["layers"].tolist(), "dims": DIMS, "regressor": "ols"}, open(RESULTS_DIR / "summary_exp4.json", "w"), indent=1)
    log("tests done")

# ------------------------------------------------------------------ plots
def phase_plots():
    import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt; from citext import plotting as P
    res = pd.read_csv(RESULTS_DIR / "exp4_local_tests.csv"); r0 = res[res.hyp == "H0"]
    P.setup(); fig, ax = plt.subplots(figsize=P.SINGLE)
    names = {"mean_last": ("mean, last layer", P.CAT[0], "-"), "mean_mid": ("mean, middle layer", P.CAT[0], "--"), "tok_last": ("last token, last layer", P.CAT[6], "-"), "tok_mid": ("last token, middle layer", P.CAT[6], "--")}
    for name, (lab, col, ls) in names.items():
        d = r0[r0.psi.str.startswith(name + ":")].copy(); d["dim"] = d.psi.str.split(":").str[1].astype(int); d = d.sort_values("dim")
        ax.errorbar(d.dim, d.rho, yerr=1.96 * d.se, marker="o", ms=3.2, capsize=2, color=col, ls=ls, lw=1.2, label=lab)
    for pn, mk, col in (("E1", "s", P.CAT[1]), ("E2", "D", P.CAT[2])):
        e = r0[r0.psi == pn].iloc[0]; ax.errorbar([e.d], [e.rho], yerr=[1.96 * e.se], fmt=mk, ms=4.5, color=col, capsize=2, label=f"$\\psi = {pn[0]}_{pn[1]}$")
    m = float(r0[r0.psi == "none"].rho.iloc[0]); ax.axhline(m, color=P.MUTED, ls=":", lw=0.9); ax.annotate("unadjusted correlation", (64, m), xytext=(2, 3), textcoords="offset points", fontsize=6.5, color=P.INK2)
    ax.axhline(0, color=P.AXIS, lw=0.6); ax.set_xscale("log", base=2); ax.set_xticks([64, 128, 256, 384, 768]); ax.set_xticklabels(["64", "128", "256", "384", "768"]); ax.minorticks_off()
    ax.set_xlabel("dimension of $\\psi(Z)$"); ax.set_ylabel("$\\hat\\rho_\\psi$ under $H_0$"); ax.set_ylim(0, m + 0.06); ax.legend(fontsize=5.8, loc="lower left", ncol=2, frameon=False, handlelength=2.2, columnspacing=1.0)
    P.savefig(fig, "exp4_local_dims.pdf"); log("exp4_local_dims.pdf")

# ------------------------------------------------------------------ macros
def phase_macros(model, write: bool):
    """\\resFour* block for paper/results_macros.tex (PAPER_DIR)."""
    from citext.paths import PAPER_DIR
    res = pd.read_csv(RESULTS_DIR / "exp4_local_tests.csv"); cur = pd.read_csv(RESULTS_DIR / "exp4_local_curve.csv"); summ = json.load(open(RESULTS_DIR / "summary_exp4.json"))
    r0 = res[res.hyp == "H0"].set_index("psi"); f3 = lambda v: f"{v:.3f}"; pct = lambda v: f"{100*v:.0f}\\%"
    labelled = summ["n_rows"] / summ.get("n_generated", summ["n_rows"])
    log_path = Path(os.environ.get("EXP4_LOG", "")) if os.environ.get("EXP4_LOG") else None
    hours = "TBD"
    if log_path and log_path.exists():
        import re as _re; t = [int(m.group(1)) for m in _re.finditer(r"\[\s*(\d+)s\]\s+\d+/\d+ posts", log_path.read_text())]
        if t: hours = f"{(t[-1] - t[0]) / 3600 * len(t) / max(len(t) - 1, 1):.1f}"
    views = {"MeanLast": "mean_last", "MeanMid": "mean_mid", "TokLast": "tok_last", "TokMid": "tok_mid"}
    W = {64: "SixtyFour", 256: "TwoFiftySix", 384: "ThreeEightyFour", 768: "SevenSixtyEight", 1000: "OneK", 2000: "TwoK"}   # LaTeX command names cannot contain digits
    M = {"resFourModel": model.split("/")[-1].replace("Qwen3-1.7B", "Qwen3-1.7B"), "resFourParams": "1.7-billion" if "1.7B" in model else "TBD", "resFourLayers": str(summ["layers"][0]), "resFourHidden": "2048" if "1.7B" in model else "TBD",
         "resFourMidLayer": str(summ["layers"][1]), "resFourLabelled": pct(labelled), "resFourGenHours": hours, "resFourN": f"{summ['n_rows']:,}".replace(",", "{,}"),
         "resFourMargNull": f3(summ["unadjusted"]["H0"]), "resFourMargAlt": f3(summ["unadjusted"]["H1"]),
         "resFourRhoEone": f3(r0.loc["E1", "rho"]), "resFourSeEone": f3(r0.loc["E1", "se"]), "resFourRhoEtwo": f3(r0.loc["E2", "rho"]), "resFourRValphaEone": f3(r0.loc["E1", "RV_alpha"]),
         "resFourRtwoXEone": pct(max(r0.loc["E1", "R2_X"], 0)), "resFourRtwoYEone": pct(max(r0.loc["E1", "R2_Y"], 0))}
    for key, name in views.items():
        for d in (64, 256, 384, 768):
            k = f"{name}:{d}"
            if k in r0.index: M[f"resFourRho{key}{W[d]}"] = f3(r0.loc[k, "rho"]); M[f"resFourRtwoX{key}{W[d]}"] = pct(max(r0.loc[k, "R2_X"], 0)); M[f"resFourRtwoY{key}{W[d]}"] = pct(max(r0.loc[k, "R2_Y"], 0))
            if k in r0.index and "bench_E1" in r0.columns and not np.isnan(r0.loc[k, "bench_E1"]): M[f"resFourBench{key}{W[d]}"] = f3(r0.loc[k, "bench_E1"])
        sub = r0[r0.index.str.startswith(name + ":")]; M[f"resFourRhoMin{key}"] = f3(sub.rho.min()); M[f"resFourRhoMax{key}"] = f3(sub.rho.max())
    hv = r0[r0.index.str.contains(":") & ~r0.index.str.startswith("[")]; M["resFourRhoMinAll"] = f3(hv.rho.min()); M["resFourRhoMaxAll"] = f3(hv.rho.max()); M["resFourBestView"] = hv.rho.abs().idxmin().replace("_", "\\_")
    M["resFourBenchMax"] = f3(hv.bench_E1.max()) if "bench_E1" in hv.columns else "TBD"
    for key, name in views.items():
        k = f"[E1,{name}:256]"
        if k in r0.index: M[f"resFourRhoEone{key}TwoFiftySix"] = f3(r0.loc[k, "rho"])
    for pn, key in (("E1", "Eone"), ("mean_last:256", "MeanLast")):
        c = cur[cur.psi == pn]
        for nn in (1000, 2000):
            cc = c[c.n == nn]
            if len(cc): M[f"resFourCurve{key}{W[nn]}"] = f3(cc.rho.median()); M[f"resFourRej{key}{W[nn]}"] = pct(cc.reject.mean())
    lines = "\n".join(f"\\newcommand{{\\{k}}}{{{v}}}" for k, v in M.items()); print(lines)
    if write:
        MAC = PAPER_DIR / "results_macros.tex"; s = MAC.read_text(); head = "% ---------- Experiment 4 (local generator) ----------"
        keep = [l for l in s.splitlines() if not re.match(r"\\newcommand\{\\resFour", l) and not l.startswith("% ---------- Experiment 4")]
        MAC.write_text("\n".join(keep).rstrip("\n") + "\n" + head + "\n" + lines + "\n"); print("written to", MAC)

if __name__ == "__main__":
    ap = argparse.ArgumentParser(); ap.add_argument("--only", default="gen,hidden,test,plots"); ap.add_argument("--n", type=int, default=3000); ap.add_argument("--batch", type=int, default=10)
    ap.add_argument("--model", default="Qwen/Qwen3-1.7B"); ap.add_argument("--subsamples", type=int, default=50); ap.add_argument("--write", action="store_true")
    a = ap.parse_args(); ph = a.only.split(",")
    if "gen" in ph: phase_gen(a.model, a.n, a.batch)
    if "hidden" in ph: phase_hidden(a.model, a.n, a.batch)
    if "test" in ph: phase_test(a.model, a.n, a.subsamples)
    if "plots" in ph: phase_plots()
    if "macros" in ph: phase_macros(a.model, "--write" in sys.argv)
    log("ALL DONE")
